// Get input JSON from previous node
const input = $input.item.json.output.results;

// Initialize an array to hold all keywords
let allKeywords = [];

// Loop through each URL result
input.forEach(item => {
  // Extract one-word, two-word, three-word keywords
  ['one_word_keywords', 'two_word_keywords', 'three_word_keywords'].forEach(type => {
    if (item[type]) {
      item[type].forEach(kwObj => {
        allKeywords.push(kwObj.keyword);
      });
    }
  });
});

// Remove duplicates (optional)
allKeywords = [...new Set(allKeywords)];

// Convert to comma-separated string
const keywordsString = allKeywords.map(k => `"${k}"`).join(', ');

// Return as JSON
return [
  {
    json: {
      "Keyword": keywordsString
    }
  }
];

const data = $input.first().json.output;

let formattedText = '';

data.forEach(section => {
  formattedText += `H2: ${section.h2}\n`;

  section.h3.forEach(sub => {
    formattedText += `H3: ${sub}\n`;
  });

  formattedText += `\n`; // extra space between sections
});

return [
  {
    json: {
      text: formattedText.trim()
    }
  }
];

// Get all input items
const items = $input.all();

if (items.length < 2) {
  return items;
}

const item1 = items[0].json;
const item2 = items[1].json;

// Deep merge: item1 is the base, item2 fills in any missing/null fields
const merged = { ...item1 };

for (const key of Object.keys(item2)) {
  // If the base value is null/undefined/empty but item2 has a value, use item2's
  if (
    merged[key] === null ||
    merged[key] === undefined ||
    merged[key] === ""
  ) {
    merged[key] = item2[key];
  }

  // For arrays, merge unique values
  if (Array.isArray(merged[key]) && Array.isArray(item2[key])) {
    merged[key] = [...new Set([...merged[key], ...item2[key]])];
  }
}

return [{ json: merged }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

