  .sort((a, b) => {
    const numA = parseInt(a.replace('most_googled_question', ''));
    const numB = parseInt(b.replace('most_googled_question', ''));
    return numA - numB;
  })
  .map(key => input[key]);

// Return as single item with array
return [
  {
    json: {
      questions: questionsArray
    }
  }
];

